'use strict';

const fs = require('fs');
const fsp = fs.promises;
const path = require('path');
const crypto = require('crypto');

const TMP_DIR_NAME = '.syncbox-tmp';

function hasLoneSurrogate(str) {
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    if (code >= 0xd800 && code <= 0xdbff) {
      const next = str.charCodeAt(i + 1);
      if (!(next >= 0xdc00 && next <= 0xdfff)) return true;
      i++;
    } else if (code >= 0xdc00 && code <= 0xdfff) {
      return true;
    }
  }
  return false;
}

function isValidSegment(segment) {
  if (segment === '' || segment === '.' || segment === '..') return false;
  if (segment.includes('�')) return false;
  if (hasLoneSurrogate(segment)) return false;
  return true;
}

// rawKeyPath is the raw (still percent-encoded) part of the URL after
// "/blobs/". Returns the decoded POSIX-style key, or null if it is not a
// valid, safely routable key (directory traversal, absolute path, empty
// segments, malformed encoding, unrepresentable filename, ...).
function parseBlobKey(rawKeyPath) {
  if (rawKeyPath === '') return null;

  const rawSegments = rawKeyPath.split('/');
  const decodedSegments = [];
  for (const rawSegment of rawSegments) {
    if (rawSegment === '') return null;
    let decoded;
    try {
      decoded = decodeURIComponent(rawSegment);
    } catch {
      return null;
    }
    decodedSegments.push(decoded);
  }

  // Re-split after decoding: a percent-encoded "/" inside a raw segment
  // (e.g. "..%2Fx") only becomes a path separator once decoded, and must
  // go through the same traversal checks as a literal "/" would.
  const key = decodedSegments.join('/');
  const finalSegments = key.split('/');
  for (const segment of finalSegments) {
    if (!isValidSegment(segment)) return null;
  }

  return key;
}

function resolveDestPath(dataDir, key) {
  const root = path.resolve(dataDir);
  const dest = path.resolve(root, key);
  if (dest !== root && !dest.startsWith(root + path.sep)) {
    throw new Error('key escapes data dir');
  }
  return dest;
}

async function putBlob(dataDir, key, buffer) {
  const destPath = resolveDestPath(dataDir, key);
  const tmpDir = path.join(dataDir, TMP_DIR_NAME);
  await fsp.mkdir(tmpDir, { recursive: true });
  await fsp.mkdir(path.dirname(destPath), { recursive: true });

  const tempPath = path.join(tmpDir, `${crypto.randomBytes(16).toString('hex')}.tmp`);
  try {
    await fsp.writeFile(tempPath, buffer);
    await fsp.rename(tempPath, destPath);
  } catch (err) {
    await fsp.unlink(tempPath).catch(() => {});
    throw err;
  }

  const sha256 = crypto.createHash('sha256').update(buffer).digest('hex');
  return { key, sha256, size: buffer.length };
}

async function getBlob(dataDir, key) {
  const srcPath = resolveDestPath(dataDir, key);
  try {
    return await fsp.readFile(srcPath);
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'EISDIR') return null;
    throw err;
  }
}

// Returns true if a blob existed at `key` and was deleted, false if there
// was nothing to delete (including when `key` names a directory rather
// than a blob, mirroring getBlob's treatment of that case as not-found).
async function deleteBlob(dataDir, key) {
  const targetPath = resolveDestPath(dataDir, key);
  try {
    await fsp.unlink(targetPath);
    return true;
  } catch (err) {
    if (err.code === 'ENOENT' || err.code === 'EISDIR') return false;
    throw err;
  }
}

function hashFile(filePath) {
  return new Promise((resolve, reject) => {
    const hash = crypto.createHash('sha256');
    const stream = fs.createReadStream(filePath);
    stream.on('data', (chunk) => hash.update(chunk));
    stream.on('end', () => resolve(hash.digest('hex')));
    stream.on('error', reject);
  });
}

async function collectFiles(dir, baseDir, out) {
  const entries = await fsp.readdir(dir, { withFileTypes: true });
  for (const entry of entries) {
    if (dir === baseDir && entry.name === TMP_DIR_NAME) continue;
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      await collectFiles(full, baseDir, out);
    } else if (entry.isFile()) {
      out.push(full);
    }
  }
}

async function listBlobs(dataDir) {
  const files = [];
  await collectFiles(dataDir, dataDir, files);

  const items = [];
  for (const full of files) {
    try {
      const stat = await fsp.stat(full);
      const sha256 = await hashFile(full);
      const key = path.relative(dataDir, full).split(path.sep).join('/');
      items.push({
        key,
        size: stat.size,
        sha256,
        modified_at: stat.mtime.toISOString(),
      });
    } catch {
      // File disappeared or became unreadable mid-scan; skip it rather
      // than fail the whole listing.
    }
  }

  items.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
  return items;
}

module.exports = { parseBlobKey, putBlob, getBlob, deleteBlob, listBlobs };

